function renderRecordCoverage(){const c=recordCoverage(report.results);$('observed').textContent=`${c.observed} / ${c.total}`;$('observed').title=`${c.notObserved} not observed; ${c.unassessed} not assessed or presence unknown. Unassessed entries do not establish either a record or a reference genotype.`;$('observed').nextElementSibling.textContent=`Catalog only: ${c.notObserved} not observed; ${c.unassessed} not assessed / unknown`;}
function error(message){$('error').textContent=message;$('error').hidden=false;$('status').textContent='';}
function clearError(){$('error').hidden=true;$('error').textContent='';}
function busy(value){$('analyze').disabled=value||!selectedFile||!catalog;$('file').disabled=value;$('build').disabled=value;$('sample').disabled=value;$('catalog-file').disabled=value;$('cancel').hidden=!value;}
function catalogInfo(){$('catalog-title').textContent=`${catalog.records.length} SNP positions${shortVariantLibrary?' + '+shortVariantLibrary.records.length.toLocaleString()+' short-indel entries':''} · ${new Set(catalog.records.map(r=>r.gene)).size} gene / locus labels`;$('catalog-meta').textContent=`Catalog ${catalog.version} · Snapshot assembled ${new Date(catalog.retrievedAt).toLocaleDateString()} · ${catalog.records.filter(r=>r.association).length} API-linked research associations pending review · GRCh37 / GRCh38 when available${catalog.clinicalReleaseDate?' · ClinVar snapshot '+catalog.clinicalReleaseDate:''}`;const categories=[...new Set(catalog.records.map(r=>r.category))].sort();$('category').innerHTML='<option value="">All categories</option>'+categories.map(c=>`<option>${esc(c)}</option>`).join('');}
function literatureDetails(r){return `<h3>Evidence review status</h3><p>${esc(r.reviewStatus||'Custom catalog; review status unspecified')}</p>${r.association?`<h3>Linked study association</h3><p>${esc(r.association.trait)} · Reported allele ${esc(r.association.reportedAllele)} · p = ${esc(r.association.pvalue)}</p><p>Reported study effect: ${esc(r.association.reportedEffect||'Not supplied by the API; no effect size inferred')}.</p><p class="small">${esc(r.association.studyAncestry)}. ${esc(r.association.alleleHarmonization||"Study allele harmonization pending")}. ${esc(r.association.selection)}. Gene labels may be reported or nearby loci; they do not establish a causal gene.</p>`:''}<h3>PubMed literature</h3>${r.literature?.length?`<ul>${r.literature.map(p=>`<li><a href="${esc(p.url)}" target="_blank" rel="noreferrer">${esc(p.title)}</a><p class="small">PMID ${esc(p.pmid)} · ${esc(p.journal)} · ${esc(p.date)}${p.relationship?' · '+esc(p.relationship):' · Study linked by GWAS Catalog'}</p></li>`).join('')}</ul>`:'<p>No PubMed metadata attached.</p>'}<p class="small">Publication indexing does not establish clinical validity. <a href="https://www.ncbi.nlm.nih.gov/About/disclaimer.html" target="_blank" rel="noreferrer">NCBI disclaimer and copyright notice</a>.</p>`;}
function select(file){if(!file)return;clearError();if(/\.(cram|bam)$/i.test(file.name)){error('CRAM/BAM contain aligned reads. Use the local CRAM preparation workflow described below to produce a filtered VCF; direct browser decoding is not supported.');return;}if(!/\.(vcf|gz|txt|tsv)$/i.test(file.name)){error('Choose a VCF, VCF.GZ, or raw consumer TXT/TSV. Extract ZIP archives first.');return;}selectedFile=file;$('file-label').textContent=`${file.name} · ${(file.size/1024/1024).toFixed(1)} MB`;$('analyze').disabled=!catalog;}
function clearReport(){organizer={};researchFilters={};selectedScore=null;scoreBrowse=scoreBrowseOptions();$('print-report').replaceChildren();$('research-list').replaceChildren();savedSnapshot=false;$('analysis-notes').value='';$('analysis-comparison').replaceChildren();$('snapshot-status').textContent='';$('investigation-dialog').close();report=null;shown=[];$('report-area').hidden=true;$('rows').replaceChildren();$('trait-groups').replaceChildren();$('pgs-results').replaceChildren();$('key-genes-results').replaceChildren();$('variant-content').replaceChildren();$('variant-dialog').close();}
function analyze(file,demo=false){clearError();clearReport();isDemo=demo;busy(true);$('status').textContent='Reading locally…';worker=new Worker('./worker.js',{type:'module'});worker.onmessage=({data})=>{
  if(data.type==='progress'){$('status').textContent=`Scanning ${data.lines.toLocaleString()} lines locally…`;return;}
  worker.terminate();worker=null;busy(false);
  if(data.type==='error'){error(data.message);return;}
  report=data.report;report.inputFile=file.name;report.syntheticDemo=demo;$('status').textContent='Analysis complete. Your input file was not uploaded or saved.';$('report-area').hidden=false;$('report-label').textContent=demo?'SYNTHETIC DEMO · NOT YOUR GENOME':'YOUR LOCAL REPORT';$('report-name').textContent=demo?'Explore a sample genome panel':'Traits & variants';$('report-meta').textContent=`${report.format} · ${report.build}${report.sample?' · Sample: '+report.sample:''} · ${file.name}`;
  renderRecordCoverage();$('present').textContent=report.results.filter(r=>r.copies>0).length;$('issues').textContent=report.results.filter(issue).length;$('scanned').textContent=report.stats.records.toLocaleString();$('warnings').innerHTML=report.warnings.map(w=>`<li>${esc(w)}</li>`).join('');render();
};worker.onerror=()=>{worker?.terminate();worker=null;busy(false);error('The analysis worker failed. Try a current browser and verify the input file.');};worker.postMessage({file,catalog,options:{pgsLibrary,shortVariantLibrary,ancestryReference,build:demo?'GRCh38':$('build').value||null,sample:demo?'':$('sample').value.trim()}});}
function render(){if(!report)return;const q=$('search').value.toLowerCase(),category=$('category').value,show=$('show').value;shown=report.results.filter(r=>(!category||r.category===category)&&(!q||`${r.id} ${r.gene} ${r.trait} ${r.label} ${traitFamily(r)}`.toLowerCase().includes(q))&&(show==='all'||show==='present'&&r.copies>0||show==='called'&&r.status==='Called'||show==='issues'&&issue(r)||show==='missing'&&['Not observed','No call'].includes(r.status)));
  const order=$('sort').value,confidence={'Established':3,'Association':2,'Context-dependent':2,'Exploratory':1};shown.sort((a,b)=>order==='gene'?a.gene.localeCompare(b.gene):order==='rarity'?(a.frequency?.value??Infinity)-(b.frequency?.value??Infinity):b.priority-a.priority||(confidence[b.evidence]||0)-(confidence[a.evidence]||0)||a.gene.localeCompare(b.gene));
  $('result-count').textContent=`${shown.length} of ${report.results.length} panel entries match filters · ${activeView==='traits'?'Traits A–Z · Expand for variants':'Click a gene for sources and interpretation'}`;$('empty').hidden=!!shown.length;
  // Bound DOM size for large custom catalogs; filtering is applied to the full report.
  $('rows').innerHTML=shown.slice(0,300).map(r=>`<tr><td><button class="gene-btn" data-id="${esc(r.id)}">${esc(r.gene)} ↗</button><small class="mono">${esc(r.id)} · ${esc(r.label)}</small></td><td>${esc(r.trait)}<small>${esc(r.category)}</small></td><td class="mono">${esc(r.genotype)}<small>${r.copies===null?'Not interpreted':`${r.copies} × ${esc(r.effectAllele)} tracked allele`}</small></td><td>${directionBadge(r)}<small>For ${esc(r.effectAllele)} allele</small></td><td><span class="pill tier${r.priority}">${esc(r.priorityLabel)}</span><small>${esc(r.evidence)}</small></td><td><div class="frequency"><span class="mono">${pct(r.frequency?.value)}</span></div><small>${esc(r.effectAllele)} allele · ${esc(r.rarity)}</small><small>${esc(r.frequency?.population||'Population frequency unavailable')}</small></td><td class="${r.status==='Called'?'called':'withheld'}">${esc(r.status)}<small>${r.status==='Called'&&report.format!=='VCF'?'Array call; unconfirmed':''}</small></td></tr>`).join('');
  renderTraits();renderScores();renderKeyGenes();renderWorkspaceViews();renderResearchList();
  if(shown.length>300&&activeView==='variants')$('result-count').textContent+=` · Showing first 300; narrow filters or export all`;
}
function details(id){const r=report.results.find(r=>r.id===id);if(!r)return;const m=r.mappings[report.build];$('variant-content').innerHTML=`<p class="eyebrow">${isDemo?'SYNTHETIC EXAMPLE · NOT YOUR GENOME · ':''}${esc(r.category)} · ${esc(r.id)}</p><h2>${esc(r.gene)} <span class="muted">${esc(r.label)}</span></h2><p>${esc(r.trait)}</p><div class="detail-grid"><div><small>Genotype / call status</small><strong class="mono">${esc(r.genotype)}</strong><p>${esc(r.status)}</p></div><div><small>Tracked allele frequency</small><strong>${pct(r.frequency?.value)} · ${esc(r.effectAllele)}</strong><p>${esc(r.frequency?.population||'Unknown population frequency')}</p></div><div><small>Relevance for this trait</small>${esc(r.priorityLabel)}</div><div><small>Evidence category</small>${esc(r.evidence)}</div></div><h3>What this result means</h3><p><strong>${esc(r.category==='Pharmacogenetic context'?'A component call does not establish a star allele, medication response, or dose.':r.category==='ClinVar review'?'A classification describes the exact variant; it does not establish a personal diagnosis.':r.directionInterpretation||personalDirection(r))}</strong></p>${directionDetails(r)}<p>${esc(r.interpretation)}</p>${clinicalDetails(r)}${pharmacogeneticDetails(r)}<h3>Interpretation limits</h3><p>${esc(r.caution)}</p><ul>${r.notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul><h3>Exact identity</h3><p class="mono">${esc(report.build)} · ${esc(m?.chrom??'unmapped')}:${esc(m?.position??'—')} · Expected REF ${esc(m?.ref??'—')} · Allowed ${esc(m?.alleles.join('/')??'—')}</p><p class="small">Genotypes are displayed as allele counts, without haplotype inference. No universal effect size or absolute risk has been assigned.</p><h3>Frequency provenance</h3><p>${r.frequency?`${esc(r.frequency.alleleCount??'Unknown')} allele observations / ${esc(r.frequency.alleleNumber??'unknown')} alleles sampled. `:''}Reference retrieved ${r.frequency?esc(r.referenceRetrievedAt||report.referenceRetrievedAt)+'. These are allele frequencies, not disease or genotype frequencies.':'— no population allele frequency is installed for this record.'}</p>${literatureDetails(r)}<h3>Evidence sources</h3><ul>${r.sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noreferrer">${esc(s.label)} ↗</a></li>`).join('')}${/^rs\d+$/.test(r.rsID||r.id)?`<li><a href="https://www.ensembl.org/Homo_sapiens/Variation/Explore?v=${encodeURIComponent(r.rsID||r.id)}" target="_blank" rel="noreferrer">Ensembl variant record ↗</a></li>`:''}</ul><p class="small muted">Opening an external source shares that requested public variant URL with the source website; your input file is not sent.</p>`;$('variant-content').insertAdjacentHTML('afterbegin',organizerControls('variant:'+r.id,organizer));if(!$('variant-dialog').open)$('variant-dialog').showModal();}
$('file').addEventListener('change',e=>select(e.target.files[0]));$('dropzone').addEventListener('dragover',e=>{e.preventDefault();$('dropzone').classList.add('drag');});$('dropzone').addEventListener('dragleave',()=>$('dropzone').classList.remove('drag'));$('dropzone').addEventListener('drop',e=>{e.preventDefault();$('dropzone').classList.remove('drag');if(!worker)select(e.dataTransfer.files[0]);});
$('analyze').addEventListener('click',()=>selectedFile&&analyze(selectedFile));$('cancel').addEventListener('click',()=>{worker?.terminate();worker=null;busy(false);$('status').textContent='Analysis cancelled. No partial report retained.';});
for(const id of ['search','category','show','sort'])$(id).addEventListener(id==='search'?'input':'change',render);
$('rows').addEventListener('click',e=>{const b=e.target.closest('[data-id]');if(b)details(b.dataset.id);});$('close-dialog').addEventListener('click',()=>$('variant-dialog').close());
$('clear').addEventListener('click',()=>{clearReport();selectedFile=null;$('file').value='';$('sample').value='';$('file-label').textContent='Choose a file or drop it here';$('status').textContent='Genetic data cleared from the app. Input files and previously downloaded exports are unchanged.';busy(false);});
$('export').addEventListener('click',()=>{if(report)downloadJson(report,`genome-report-${isDemo?'synthetic-':''}${new Date().toISOString().slice(0,10)}.json`);});
$('catalog-file').addEventListener('change',async e=>{try{clearError();const file=e.target.files[0];if(!file)return;if(file.size>50_000_000)throw Error('Catalog exceeds 50 MB.');const next=validateCatalog(JSON.parse(await file.text()));catalog=next;loadedLibraries={...loadedLibraries,base:null,clinical:null,cpic:null,research:null,custom:next};renderLibraryInventory();clearReport();catalogInfo();busy(false);$('status').textContent='Custom catalog loaded. Analyze your file again to use it.';}catch(e){error(e.message);}finally{$('catalog-file').value='';}});
try{
  const [base,scores,populations,clinical,cpic,indels,research,psychiatricGWAS,validity,drugPairs,expert,dosage,scoreDistributions,sensitivityDistributions]=await Promise.allSettled([editionFetch('./data/catalog.json').then(r=>r.json()),editionFetch('./data/pgs-library.json').then(r=>r.json()),editionFetch('./data/pgs-populations.json').then(r=>{if(!r.ok)throw Error('Population reference unavailable');return r.json();}),editionFetch('./data/clinical-library.json').then(r=>{if(!r.ok)throw Error('ClinVar library unavailable');return r.json();}),editionFetch('./data/cpic-library.json').then(r=>{if(!r.ok)throw Error('CPIC library unavailable');return r.json();}),editionFetch('./data/short-variant-library.json').then(r=>{if(!r.ok)throw Error('Short-indel library unavailable');return r.json();}),editionFetch('./data/research-library.json').then(r=>{if(!r.ok)throw Error('Research library unavailable');return r.json();}),editionFetch('./data/psychiatric-gwas-library.json').then(r=>{if(!r.ok)throw Error('Psychiatric GWAS source index unavailable');return r.json();}),editionFetch('./data/gene-validity-library.json').then(r=>{if(!r.ok)throw Error('ClinGen library unavailable');return r.json();}),editionFetch('./data/gene-drug-library.json').then(r=>{if(!r.ok)throw Error('CPIC guideline library unavailable');return r.json();}),editionFetch('./data/expert-assertion-library.json').then(r=>{if(!r.ok)throw Error('Expert assertion library unavailable');return r.json();}),editionFetch('./data/gene-dosage-library.json').then(r=>{if(!r.ok)throw Error('Dosage library unavailable');return r.json();}),editionFetch('./data/pgs-score-reference.json').then(r=>{if(!r.ok)throw Error('Score distributions unavailable');return r.json();}),editionFetch('./data/pgs-score-sensitivity.json').then(r=>{if(!r.ok)throw Error('Sensitivity reference unavailable');return r.json();})]);
  try{if(expert.status==='rejected')throw expert.reason;expertAssertionLibrary=validateExpertAssertions(expert.value);}catch(e){error('Disease-specific expert context unavailable: '+e.message);}
  try{if(drugPairs.status==='rejected')throw drugPairs.reason;geneDrugLibrary=validateGeneDrugs(drugPairs.value);}catch(e){error('CPIC guideline context unavailable: '+e.message);}
  try{if(validity.status==='rejected')throw validity.reason;geneValidityLibrary=validateGeneValidity(validity.value);}catch(e){error('ClinGen gene context unavailable: '+e.message);}
  try{if(dosage.status==='rejected')throw dosage.reason;geneDosageLibrary=validateGeneDosage(dosage.value);}catch(e){error('Gene-copy context unavailable: '+e.message);}
  if(populations.status==='fulfilled')pgsPopulations=populations.value;
  try{if(scoreDistributions.status==='fulfilled')scoreReference=validateScoreReference(scoreDistributions.value);}catch(e){error('European score reference unavailable: '+e.message);}
  try{if(indels.status==='rejected')throw indels.reason;shortVariantLibrary=validateShortVariantLibrary(attachExpertAssertions(indels.value,expertAssertionLibrary));$('short-variant-status').textContent=shortVariantLibrary.records.length.toLocaleString()+' short-indel citations available for normalized GRCh38 VCF. Import a previously normalized VCF with the required provenance for indel interpretation. Ordinary VCF imports retain SNP analysis. Guided preparation is not included in this public edition.';}catch(e){$('short-variant-status').textContent='Short-indel library unavailable: '+e.message;}
  if(base.status==='rejected')throw base.reason;catalog=validateCatalog(base.value);if(clinical.status==='fulfilled')catalog=mergeClinicalLibrary(catalog,attachExpertAssertions(clinical.value,expertAssertionLibrary));else error('ClinVar library unavailable; base associations remain available.');if(cpic.status==='fulfilled')catalog=mergePharmacogeneticLibrary(catalog,cpic.value);else error('CPIC library unavailable; other libraries remain available.');if(research.status==='fulfilled')catalog=mergeResearchLibrary(catalog,research.value);else error('Additional research library unavailable; other libraries remain available.');
  try{if(scores.status==='rejected')throw scores.reason;pgsLibrary=validatePGSLibrary(scores.value);$('pgs-library-status').textContent=`Published score library: ${pgsLibrary.models.length} models · ${pgsLibrary.targets.length} distinct scoring positions, analyzed alongside the ${catalog.records.length.toLocaleString()}-position interpretation library. Raw scores require complete usable calls; percentiles are not calibrated.`;}
  catch(e){$('pgs-library-status').textContent='Published score library unavailable: '+e.message;}
  try{if(sensitivityDistributions.status==='fulfilled')sensitivityReference=validateSensitivityReference(sensitivityDistributions.value);}catch(e){error('Sensitivity reference unavailable: '+e.message);}
  let psychiatricGWASLibrary=null;try{if(psychiatricGWAS.status==='rejected')throw psychiatricGWAS.reason;psychiatricGWASLibrary=validatePsychiatricGWASLibrary(psychiatricGWAS.value);}catch(e){if(!(e instanceof LibraryNotIncludedError))error('Psychiatric GWAS source index unavailable: '+e.message);}
  loadedLibraries={base:base.value,clinical:clinical.status==='fulfilled'?clinical.value:null,cpic:cpic.status==='fulfilled'?cpic.value:null,research:research.status==='fulfilled'?research.value:null,psychiatricGWAS:psychiatricGWASLibrary,indels:shortVariantLibrary,scores:pgsLibrary,populations:pgsPopulations,scoreDistributions:scoreReference,scoreSensitivity:sensitivityReference,validity:geneValidityLibrary,drugPairs:geneDrugLibrary,expert:expertAssertionLibrary,dosage:geneDosageLibrary};
  try{const response=await editionFetch('./data/pgs-evaluation.json');if(!response.ok)throw Error('Snapshot unavailable');evaluationLibrary=validatePGSEvaluationLibrary(await response.json());}catch(e){if(!(e instanceof LibraryNotIncludedError))console.warn('Optional offline PGS evaluation evidence unavailable: '+e.message);}
  try{const response=await editionFetch('./data/ancestry-reference.json');const numericalResponse=await editionFetch('./data/ancestry-numerical-verification.json').catch(()=>null);ancestryReference=await loadAncestryReference(response,numericalResponse);$('ancestry-status').textContent=`Ancestry reference: ${ancestryReference.markers.length.toLocaleString()} markers · ${ancestryReference.populations.length} sampled populations · broad mixture estimates and population similarity. Requires 90% usable marker coverage; country percentages are not calculated.`;}catch(e){$('ancestry-status').textContent='Ancestry analysis unavailable: '+e.message;}
  loadedLibraries.ancestry=ancestryReference;$('ancestry-status').hidden=Boolean(ancestryReference);renderLibraryInventory();catalogInfo();busy(false);
}catch(e){busy(false);error('Could not load reference catalog: '+e.message);}

function renderLibraryInventory(){
 $('library-inventory').innerHTML=libraryInventory(loadedLibraries).map(r=>`<article><h3>${esc(r.name)}</h3><p><strong>${esc(r.count)}</strong></p><p class="small">${esc(r.scope)}</p><p class="small muted">Version ${esc(r.version)}${r.releaseDate?' · Source release '+esc(r.releaseDate):''} · Retrieved ${esc(r.retrievedAt?.slice(0,10)||'not recorded')}${r.url?` · <a href="${esc(r.url)}" target="_blank" rel="noreferrer">Source ↗</a>`:''}</p></article>`).join('')+psychiatricAvailabilityHtml(loadedLibraries.scores);
}

function geneDosageDetails(entry){
 const rows=geneDosageFor(entry.genes,geneDosageLibrary);if(!rows.length)return '';
 return '<details class="score-note"><summary>ClinGen gene-copy evidence ('+rows.length+')</summary><p>'+esc(DOSAGE_SCOPE)+'</p><p class="small">Haploinsufficiency asks whether one functional copy is insufficient. Triplosensitivity asks whether an extra copy can cause disease. Source categories are evidence labels, not a personal risk scale.</p>'+rows.map(r=>'<article><h4>'+esc(r.gene)+'</h4>'+[['haploinsufficiency','Loss of a functional copy'],['triplosensitivity','Gain of a gene copy']].map(([key,label])=>{const d=r[key];return '<p><strong>'+label+':</strong> '+esc(d.description)+' ('+esc(d.score)+'). '+esc(dosageMeaning(d.score))+'</p>'+(d.diseaseId?'<p class="small">Source disease identifier: '+esc(d.diseaseId)+'</p>':'')+(d.pmids.length?'<p class="small">Source studies: '+d.pmids.map(p=>'<a href="https://pubmed.ncbi.nlm.nih.gov/'+esc(p)+'/" target="_blank" rel="noreferrer">PMID '+esc(p)+'</a>').join(' · ')+'</p>':'');}).join('')+'<p class="small">Evaluated '+esc(r.evaluatedAt)+' · Source snapshot '+esc(geneDosageLibrary.releaseDate)+' · <a href="'+esc(r.url)+'" target="_blank" rel="noreferrer">Full dosage curation ↗</a></p></article>').join('')+'</details>';
}


function directionBadge(r){if(r.category==='Pharmacogenetic context')return '<span class="pill">Definition component</span>';if(r.category==='ClinVar review')return '<span class="pill">Allele-specific classification</span>';const d=r.effectDirection||effectDirection(r);return `<span class="pill direction-${esc(d.direction)}">${esc(d.label)}</span>`;}
function directionDetails(r){if(['ClinVar review','Pharmacogenetic context'].includes(r.category))return '';const d=r.effectDirection||effectDirection(r);return `<div class="effect-note">${directionBadge(r)}<p>${esc(d.text)}</p><p class="small">${esc(d.caveat)}</p>${d.raw?`<p class="small">Exact reported effect: ${esc(d.raw)}</p>`:''}${d.source?`<a class="small" href="${esc(d.source)}" target="_blank" rel="noreferrer">Direction evidence ↗</a>`:''}</div>`;}
function renderTraits(){
  $('trait-groups').hidden=activeView!=='traits';$('variant-table').hidden=activeView!=='variants';$('pgs-results').hidden=activeView!=='scores';$('variant-filters').hidden=['scores','key-genes','overview','investigate','ancestry'].includes(activeView);$('key-genes-results').hidden=activeView!=='key-genes';$('key-genes-view').setAttribute('aria-pressed',String(activeView==='key-genes'));
  $('traits-view').setAttribute('aria-pressed',String(activeView==='traits'));$('variants-view').setAttribute('aria-pressed',String(activeView==='variants'));$('scores-view').setAttribute('aria-pressed',String(activeView==='scores'));
  const matches=new Set(shown.map(r=>r.id)),rank=new Map(shown.map((r,i)=>[r.id,i]));
  const groups=clusterTraits(report.results).map(g=>({...g,visible:g.variants.filter(r=>matches.has(r.id)).sort((a,b)=>rank.get(a.id)-rank.get(b.id))})).filter(g=>g.visible.length);
  $('trait-groups').innerHTML=groups.slice(0,300).map(g=>`<details class="trait-card"><summary><span><strong>${esc(g.name)}</strong><small>${g.variants.length} panel variant${g.variants.length===1?'':'s'} · ${g.called} called · ${g.visible.length} match filters</small></span><span class="pill">Expand variants ↓</span></summary><div class="trait-body"><p class="small">${g.endpoints.length} study endpoint${g.endpoints.length===1?'':'s'} grouped for browsing. Each row retains its exact trait; these are not necessarily independent genetic signals.</p>${traitScoreNote(g)}${g.visible.slice(0,300).map(r=>`<article class="trait-variant"><div><button class="gene-btn" data-id="${esc(r.id)}">${esc(r.gene)} · ${esc(r.id)} ↗</button><p class="small">${esc(r.trait)}</p></div><div><span class="mono">${esc(r.genotype)}</span> · ${esc(r.status)}${report.format!=='VCF'&&r.status==='Called'?' · Array call; unconfirmed':''}<p>${directionBadge(r)}</p><p class="small">${esc(r.directionInterpretation||personalDirection(r))}</p></div></article>`).join('')}${g.visible.length>300?'<p>First 300 matching variants shown. Narrow the filters or export the full report.</p>':''}</div></details>`).join('');
  if(groups.length>300)$('result-count').textContent+=' · First 300 trait groups shown; narrow filters';
}
for(const view of ['traits','variants','scores','key-genes','overview','investigate','ancestry'])$(view+'-view').addEventListener('click',()=>{activeView=view;render();});
$('trait-groups').addEventListener('click',e=>{const b=e.target.closest('[data-id]');if(b)details(b.dataset.id);const s=e.target.closest('[data-score-family]');if(s){activeView='scores';$('search').value=s.dataset.scoreFamily;render();}});

const scoreNumber=n=>n===null||n===undefined?'—':Number(n).toLocaleString(undefined,{maximumSignificantDigits:7});
function traitScoreNote(group){
  const models=(report.polygenicScores||[]).filter(s=>scoreFamily(s)===scoreFamily({family:group.name}));
  if(!models.length)return `<div class="score-note"><strong>Polygenic score / percentile: unavailable</strong><p>${esc(group.score.reason)}</p><a href="${PGS_METHODS}" target="_blank" rel="noreferrer">About score calibration ↗</a></div>`;
  return `<div class="score-note"><strong>Published score model installed</strong>${models.map(s=>`<p>${esc(s.id)} · ${s.matched}/${s.total} usable terms · ${esc(s.status)}</p>`).join('')}<button class="secondary" data-score-family="${esc(group.name)}">Review score and all scoring variants ↗</button></div>`;
}
let preparedScoreReport=null;
let scoreBrowse=scoreBrowseOptions();
$('pgs-results').addEventListener('click',event=>{const button=event.target.closest('[data-score-sort]');if(!button)return;const key=button.dataset.scoreSort;scoreBrowse={...scoreBrowse,sortBy:key,direction:scoreBrowse.sortBy===key&&scoreBrowse.direction==='asc'?'desc':'asc'};renderScores();$('pgs-results').querySelector('[data-score-sort="'+key+'"]').focus();});
$('pgs-results').addEventListener('change',event=>{if(event.target.id!=='hide-unavailable-scores')return;scoreBrowse={...scoreBrowse,hideUnavailable:event.target.checked};renderScores();$('hide-unavailable-scores').focus();});
function renderScores(){
  if(!report)return;
  const activeModels=activeScoreModels(report.polygenicScores||[]);
  if(!savedSnapshot&&preparedScoreReport!==report){for(const m of report.polygenicScores||[])europeanScore(m,pgsPopulations,scoreReference,sensitivityReference);preparedScoreReport=report;}
  const q=$('search').value.toLowerCase();
  const models=browseScores(filterResearchScores(activeModels,researchFilters,organizer).filter(m=>`${m.id} ${m.name} ${m.trait} ${m.family} ${scoreFamily(m)} ${m.terms.map(t=>`${t.id} ${t.sourceId} ${t.locus}`).join(' ')}`.toLowerCase().includes(q)),scoreBrowse);
  if(activeView==='scores'){const complete=models.filter(m=>m.rawSum!==null).length;$('empty').hidden=true;$('result-count').textContent=`${models.length} published ${models.length===1?'model':'models'} · ${complete} complete measured ${complete===1?'score':'scores'} · ${report.scoringTargetCount||0} distinct scoring positions · Search model, trait, gene label, or rsID`;}
$('pgs-results').innerHTML=`${withdrawnScoreNotice(report.polygenicScores||[])?'<p class="score-note">'+esc(withdrawnScoreNotice(report.polygenicScores))+'</p>':''}<p class="score-note"><strong>European reference (EUR)</strong> · Disease predisposition and trait scores appear together below. Reference ranks use 1000 Genomes European samples. Missing-genotype scenarios use European frequencies where available; this is a comparison setting, not an ancestry assessment.</p><p class="pgs-intro">Published weights are applied only within their own model. A complete raw sum is not a trait measurement or risk estimate. Percentiles need a compatible comparison population. These published models are a research starting point, not a selection of the most predictive scores. Where supplied, lifetime diagnosis figures describe a named population and age horizon; they are not personalized from your score.</p>`+researchFiltersHtml(activeModels,researchFilters)+scoreSummaryHtml(models,scoreBrowse,organizer)+'<details><summary>Compare related models</summary>'+comparisonView(models)+'</details>'+(!models.some(m=>m.id===selectedScore)?'<p class="score-note">Select a trait above to open its full explanation and scoring variants.</p>':'')+models.filter(m=>m.id===selectedScore).map(m=>{
    const reasons=Object.entries(m.reasons).map(([k,v])=>`${v} ${k.toLowerCase()}`).join(' · ');
    const {terms,matching}=visibleScoreTerms(m,q);
return `<article class="pgs-card" id="score-${esc(m.id)}"><p class="eyebrow">${esc(m.id)} · ${esc(m.name)}</p><h3 tabindex="-1" class="selected-score-heading">${esc(scoreDisplayTrait(m))}</h3>${scoreConditionHtml(m)}${organizerControls('score:'+m.id,organizer)}${m.coverageContext?`<p class="small">${esc(m.coverageContext)}</p>`:''}${analysisMethodCardNotice(report)?`<p class="score-note historical-score">${esc(analysisMethodCardNotice(report))}</p>`:''}${resultBadge(m)}${diseaseContext(m.id)}${psychologicalContext(m)}${expandedScoreContext(m)}${lifetimeRiskHtml(m)}${scoreMetrics(m)}${uncertaintyCard(m)}<p class="small"><strong>Reported discovery populations:</strong> ${esc(ancestryDescription(m.ancestry?.gwas))}<br><strong>Reported model-development populations:</strong> ${esc(ancestryDescription(m.ancestry?.dev))}<br><strong>Reported evaluation populations:</strong> ${esc(ancestryDescription(m.ancestry?.eval))}</p><p class="small">${esc(referencePopulationContext(m,scenarioPopulation))}</p>${scenarioCard(m)}${m.rawSum===null?`<details class="score-note"><summary>Incomplete calculation diagnostics</summary><p><strong>Matched-variant subtotal: ${scoreNumber(m.matchedSubtotal)}</strong><br>Incomplete diagnostic sum only. This is not the published full score and cannot be used to rank your trait or compared with other subtotals.</p></details>`:''}<p class="small">${esc(reasons||'All required terms have usable calls.')} Measured scores never treat an absent record as a reference call. The separate estimate may assume a common genotype. Strand-ambiguous homozygotes require additional evidence.</p><p class="small"><strong>Measured-score calculation:</strong> ${esc(m.calculation)}</p>${m.terms.some(t=>t.alleleMode==='effect-only')?'<p class="small">Some source terms omit the comparison allele. All reference-compatible weighted-allele orientations are retained; a measured contribution is used only when they give the same dosage. Population frequencies do not select a strand.</p>':''}<p class="small">${esc(m.interpretation)}</p><p class="small"><a href="${esc(m.catalogURL)}" target="_blank" rel="noreferrer">Model, evaluation populations & performance ↗</a> · <a href="https://doi.org/${esc(m.publication.doi)}" target="_blank" rel="noreferrer">${esc(m.publication.firstauthor)} · ${esc(m.publication.journal)} · ${esc(m.publication.date_publication)} ↗</a></p><details><summary>Model provenance and ancestry</summary><p class="small">${esc(m.publication.title)}</p><p class="small">GWAS ancestry distribution: ${esc(JSON.stringify(m.ancestry.gwas?.dist||{}))}. EUR = European; AFR = African; AMR = Hispanic/Latin American. Evaluation samples and applicability differ; your ancestry is not inferred here.</p><p class="small">${esc(studySexDescription(m.studySamples?.variantAssociation))}</p><p class="small">Published method: ${esc(m.method)}. ${esc(m.methodParameters||'No further parameters supplied')}. Publication-specific normalization is not applied to the raw sum.</p>${m.weightEvidence?`<p class="small">Source weight type: ${esc(m.sourceWeightType)}. ${esc(m.weightEvidence.method)} Verified ${m.weightEvidence.verifiedRows} rows; original weights are unchanged.</p>`:''}<p class="small">Library ${esc(m.libraryVersion)} · retrieved ${esc(m.libraryRetrievedAt)} · ${esc(m.build)}</p><p class="small"><a href="${esc(m.sourceFiles[m.build].url)}" target="_blank" rel="noreferrer">Exact harmonized weight file ↗</a></p><p class="small mono">SHA-256: ${esc(m.sourceFiles[m.build].sha256)}</p><p class="small">${esc(m.license)}</p></details><details class="pgs-terms"><summary>Scoring variants and contributions (${terms.length} shown / ${m.total})</summary>${matching>terms.length?`<p>Showing the first ${terms.length} of ${matching} matching terms. Search an rsID to narrow the table. The calculation and exported report retain all ${m.total} published terms.</p>`:''}<div class="table-wrap"><table><thead><tr><th>Variant / position</th><th>Genotype</th><th>Model alleles</th><th>Weight</th><th>Effect copies</th><th>Contribution</th><th>Scoring status</th></tr></thead><tbody>${terms.map(t=>`<tr><td><a href="https://www.ensembl.org/Homo_sapiens/Variation/Explore?v=${esc(t.id)}" target="_blank" rel="noreferrer">${esc(t.id)} ↗</a><small>${esc(t.locus)}</small><small>${esc(t.mapping?.chrom)}:${esc(t.mapping?.position)} (${esc(m.build)})</small>${t.sourceId!==t.id?`<small>Source ID ${esc(t.sourceId)}</small>`:''}</td><td class="mono">${esc(t.genotype)}</td><td>${t.alleleMode==='effect-only'?`Source ${esc(t.sourceEffectAllele)}; comparison allele not specified<small>Possible weighted alleles: ${esc(t.effectAlleleCandidates.join(' / '))}</small>`:`${esc(t.effectAllele)} effect / ${esc(t.otherAllele)} other`}${t.reverseComplemented&&t.alleleMode!=='effect-only'?`<small>Source ${esc(t.sourceEffectAllele)}/${esc(t.sourceOtherAllele)}; verified reverse complement</small>`:''}</td><td class="mono">${esc(t.weightText)}</td><td>${t.dosage??'—'}</td><td class="mono">${scoreNumber(t.contribution)}</td><td>${esc(t.status)}<small>${esc(t.note)}</small></td></tr>`).join('')}</tbody></table></div></details></article>`;
  }).join('')+(!models.length?'<p class="empty">No score models match. Clear the search, or check whether the score library loaded above.</p>':'');
  for(const model of models)$('score-'+model.id)?.insertAdjacentHTML('beforeend',methodEvidenceHtml(model)+evaluationHtml(model,evaluationLibrary));
}

function scoreMetrics(m){
 const e=m.hypotheticalEstimate,coverage=pgsCoverage(m),complete=m.rawSum!==null,value=complete?m.rawSum:e.bestGuess;
 const label=complete?'Complete measured raw sum':e.neutralTerms?'Best guess with neutral assumptions':'Common-genotype best guess';
 const range=e.unconditionalLower===null?'Cannot estimate':scoreNumber(e.unconditionalLower)+' to '+scoreNumber(e.unconditionalUpper);
return '<div class="pgs-metrics"><div><small>'+label+'</small><strong>'+ (value===null?'Cannot estimate':scoreNumber(value))+'</strong><p>'+(complete?'All model terms have usable calls.':e.lower===null?esc(e.reason):e.assumedTerms+' population-modal substitutions; '+e.neutralTerms+' neutral midpoint terms (counts may overlap).')+'</p></div><div><small>Possible raw-score range</small><strong>'+range+'</strong><p>'+(complete?'No missing-term range.':'Keeps all unresolved possibilities before common-genotype substitution. Mathematical bounds, not a confidence interval.')+'</p></div><div><small>Usable measured terms</small><strong>'+m.matched+' / '+m.total+'</strong><p>'+pct(m.variantCoverage)+' of terms · '+pct(m.absoluteWeightCoverage)+' of absolute weight. '+coverage.presentButUnusable+' present but excluded; '+coverage.notObserved+' not observed; '+coverage.unassessed+' not assessed / presence unknown. Assumed terms do not increase measured coverage.</p></div></div>'+referenceCard(m)+'';
}
function scenarioCard(m){
 const e=m.hypotheticalEstimate;
 if(m.rawSum!==null)return '';
 if(e.lower===null)return '<div class="score-note"><strong>Why an estimate cannot be made</strong><p>'+esc(e.reason)+'</p></div>';
 return '<div class="score-note"><p><strong>How the best guess works:</strong> Published weights stay fixed. Missing genotypes use the European reference population’s most common genotype where supported. Remaining ambiguity uses a neutral midpoint, which may not correspond to a real genotype or attainable score. This is a working scenario, not a statistically most-likely result. Your original calls stay unchanged.</p><details><summary>Review assumptions and affected variants ('+e.terms.length+')</summary><p>'+esc(e.bestGuessMethod)+'</p><p>After modal substitutions, retained range: '+scoreNumber(e.lower)+' to '+scoreNumber(e.upper)+'. The wider range above also allows the substituted genotypes to differ. Neither range is a confidence interval; correlated variants may make some combinations impossible.</p><p>'+esc(e.reason)+'</p><p>'+esc(e.source||'No population reference selected')+' · '+esc(e.population||'No substitution')+' · '+esc(e.retrievedAt||'')+' · Ensembl '+esc(e.ensemblReleases.join(', '))+'</p>'+e.terms.map(t=>'<p><strong>'+esc(t.id)+'</strong> · '+esc(t.originalStatus)+' · '+esc(t.method)+(t.assumedGenotypes.length?'<br>Assumed '+esc(t.assumedGenotypes.join(' or '))+' · observed population frequency '+pct(t.frequency)+' in '+t.sampleCount+' reference individuals':'')+'<br>Contribution bounds: '+scoreNumber(t.contributionLower)+' to '+scoreNumber(t.contributionUpper)+(t.centralContribution!==null?'<br>Best-guess contribution: '+scoreNumber(t.centralContribution)+' · '+esc(t.centralMethod):'')+(t.sourceURL?' · <a href="'+esc(t.sourceURL)+'" target="_blank" rel="noreferrer">Public frequency source ↗</a>':'')+'</p>').join('')+'</details></div>';
}

const expandedKeyGenes=new Set();
function renderKeyGenes(){
 if(!report)return;
 report.keyGenes=KEY_GENES.map(e=>({...e,...keyGeneSummary(e,report.results),geneDiseaseValidity:geneValidityFor(e.genes,geneValidityLibrary),geneDrugReferences:geneDrugsFor(e.genes,geneDrugLibrary),geneCopyEvidence:geneDosageFor(e.genes,geneDosageLibrary)}));
 report.geneContextLibraries={dosage:geneDosageLibrary?{version:geneDosageLibrary.version,sourceURL:geneDosageLibrary.sourceURL,sourceSha256:geneDosageLibrary.sourceSha256,releaseDate:geneDosageLibrary.releaseDate}:null,clingen:geneValidityLibrary?{version:geneValidityLibrary.version,sourceURL:geneValidityLibrary.sourceURL,sourceSha256:geneValidityLibrary.sourceSha256,releaseDate:geneValidityLibrary.releaseDate}:null,cpic:geneDrugLibrary?{version:geneDrugLibrary.version,sourceURL:geneDrugLibrary.sourceURL,sourceSha256:geneDrugLibrary.sourceSha256,retrievedAt:geneDrugLibrary.retrievedAt}:null};
 const q=$('search').value.trim().toLowerCase();
 const entries=KEY_GENES.filter(e=>[...e.genes,e.topic,...e.paragraphs,...geneValidityFor(e.genes,geneValidityLibrary).map(r=>r.disease),...geneDrugsFor(e.genes,geneDrugLibrary).map(r=>r.drug),...report.keyGenes.find(g=>g.id===e.id).variantIds].join(' ').toLowerCase().includes(q));
 if(activeView==='key-genes'){$('empty').hidden=true;$('result-count').textContent=entries.length+' key gene profiles · explanations and selected-panel calls';}
 $('key-genes-results').innerHTML='<p class="pgs-intro">Everyone has these genes. Their significance depends on specific variants, not the gene name alone. These profiles explain why they matter; the counts below describe only this app’s selected variants and cannot establish a negative clinical test.</p>'+entries.map(e=>{
 const summary=report.keyGenes.find(g=>g.id===e.id),ids=new Set(summary.variantIds),all=report.results.filter(r=>ids.has(r.id)).sort((a,b)=>Number(b.clinicalFindings?.some(c=>c.copies>0))-Number(a.clinicalFindings?.some(c=>c.copies>0))||Number(b.status==='Called')-Number(a.status==='Called')||a.id.localeCompare(b.id));
 const rows=expandedKeyGenes.has(e.id)?all:all.slice(0,20);
 return '<article class="key-gene-card"><p class="eyebrow">'+esc(e.topic)+'</p><h3>'+esc(e.genes.join(' · '))+'</h3>'+e.paragraphs.map(p=>'<p>'+esc(p)+'</p>').join('')+'<p class="small">'+e.sources.map(s=>'<a href="'+esc(s.url)+'" target="_blank" rel="noreferrer">'+esc(s.label)+' ↗</a>').join(' · ')+'</p>'+geneValidityDetails(e)+geneDrugDetails(e)+geneDosageDetails(e)+'<div class="key-gene-coverage"><strong>'+summary.calledVariants+(summary.calledVariants===1?' called variant / ':' called variants / ')+summary.listedVariants+' listed variants</strong><p>'+(summary.listedVariants===0?'No variants for these genes are installed in the loaded interpretation panel. This profile is educational.':summary.classifiedAlleleMatches?summary.classifiedAlleleMatches+(summary.classifiedAlleleMatches===1?' panel position has':' panel positions have')+' a called allele with an imported ClinVar classification. Review the exact allele evidence below; this is not a diagnosis.':summary.clinicalVariants?'No imported classified allele was identified among the sequencing calls that passed quality checks in this limited panel. Missing calls and untested variation remain unresolved.':summary.pharmacogeneticVariants?summary.pharmacogeneticVariants+' positions are CPIC definition components. Their calls do not establish a complete named allele or medication phenotype.':'These are selected association markers. Open each variant for its specific evidence and interpretation.')+'</p>'+(e.id==='APOE'?'<p>APOE type is not assigned by this app.</p>':'')+'</div>'+(all.length?'<details '+(expandedKeyGenes.has(e.id)?'open':'')+'><summary>Review listed variants ('+all.length+')</summary>'+rows.map(r=>'<div class="key-gene-variant"><button class="gene-btn" data-id="'+esc(r.id)+'">'+esc(r.id)+' ↗</button><span>'+esc(r.genotype)+' · '+esc(r.status)+'</span><small>'+esc(r.label)+' · '+esc(r.evidence)+'</small></div>').join('')+(rows.length<all.length?'<button class="secondary" data-expand-key="'+esc(e.id)+'">Show all '+all.length+' listed variants</button>':'')+'</details>':'')+'</article>';
 }).join('')+(!entries.length?'<p>No key gene profiles match this search.</p>':'');
}
$('key-genes-results').addEventListener('click',e=>{const b=e.target.closest('[data-id]');if(b)details(b.dataset.id);const more=e.target.closest('[data-expand-key]');if(more){expandedKeyGenes.add(more.dataset.expandKey);renderKeyGenes();}});

function clinicalDetails(r){return r.clinicalFindings?.length?'<section class="clinical-evidence"><h3>ClinVar allele-specific evidence</h3><p>'+(r.variantKind==='short-indel'?'Selected simple indels up to 50 inserted/deleted bases, using normalized GRCh38 representations. Calls are file-level matches, not clinical confirmation.':'Selected autosomal SNV evidence.')+' Untested variants, structural changes, missing calls and unreviewed records remain unresolved. This is not a negative gene screen.</p>'+r.clinicalFindings.map(a=>'<article class="score-note"><h4>ALT '+esc(a.allele)+' · ClinVar '+esc(a.variationId)+'</h4><p><strong>Genotype evidence:</strong> '+(a.copies===null?'Withheld':a.copies+' copies of this exact allele')+'. '+esc(a.interpretation)+'</p><p><strong>Database record classification:</strong> '+esc(a.classification)+'<br>'+esc(a.reviewStatus)+' · '+a.stars+' stars · Snapshot '+esc(a.releaseDate)+'</p>'+molecularDetails(a)+expertAssertionDetails(a)+'<details><summary>Conditions listed on this record</summary><p>Aggregate source list; the classification is not asserted separately for every condition below.</p><p>'+esc(a.conditions)+'</p></details><a href="'+esc(a.url)+'" target="_blank" rel="noreferrer">Review original ClinVar record ↗</a></article>').join('')+'</section>':'';}

function pharmacogeneticDetails(r){const p=r.pharmacogenetics;if(!p)return '';return '<section class="score-note"><h3>CPIC pharmacogenetic component</h3><p>'+esc(p.gene)+' · '+esc(p.chromosomeSequence)+':'+esc(p.chromosomalHGVS)+'</p><p>Source description: '+esc(p.sourceName)+(p.proteinHGVS?' · '+esc(p.proteinHGVS):'')+'</p><p>This position occurs in CPIC allele-definition data. A component can belong to more than one named allele, and additional variants, phase, copy-number changes and structural variation may be required. This app does not infer a complete haplotype, enzyme phenotype, activity score or dose from this call.</p><p class="small">CPIC location '+p.locationId+' · source record version '+p.locationVersion+'. Genotype quality and call status are shown separately above.</p><a href="'+esc(p.geneURL)+'" target="_blank" rel="noreferrer">CPIC gene resources ↗</a> · <a href="'+esc(p.sourceURL)+'" target="_blank" rel="noreferrer">Exact component record ↗</a></section>';}

function molecularDetails(a){return a.molecularConsequences?.length?'<h4>Molecular effect in the source record</h4><ul>'+a.molecularConsequences.map(t=>'<li><strong>'+esc(t.term.replaceAll('_',' '))+'</strong> ('+esc(t.id)+'): '+esc(explainMolecularConsequence(t))+'</li>').join('')+'</ul><p class="small">'+esc(MOLECULAR_EFFECT_SCOPE)+'</p><a href="'+MOLECULAR_EFFECT_SOURCE+'" target="_blank" rel="noreferrer">Consequence terminology ↗</a> · <a href="${esc(SEQUENCE_ONTOLOGY_SOURCE)}" target="_blank" rel="noreferrer">Sequence Ontology ↗</a>':'';}

function geneValidityDetails(entry){const rows=geneValidityFor(entry.genes,geneValidityLibrary);return '<details class="score-note"><summary>ClinGen gene–disease evidence ('+rows.length+')</summary><p>'+esc(GENE_VALIDITY_SCOPE)+'</p><p class="small">'+(geneValidityLibrary?'Source snapshot '+esc(geneValidityLibrary.releaseDate):'Library unavailable')+'</p>'+rows.map(r=>'<article><h4>'+esc(r.gene)+' · '+esc(r.disease)+'</h4><p>'+esc(r.classification)+' · '+esc(inheritanceLabel(r.inheritance))+'</p><p class="small">'+esc(r.panel)+' · '+esc(r.classificationDate.slice(0,10))+' · '+esc(r.sop)+' · '+esc(r.hgnc)+' · '+esc(r.mondo)+'</p><a href="'+esc(r.url)+'" target="_blank" rel="noreferrer">Original ClinGen curation ↗</a></article>').join('')+'</details>';}

function geneDrugDetails(entry){const rows=geneDrugsFor(entry.genes,geneDrugLibrary);if(!rows.length)return '';return '<details class="score-note"><summary>CPIC gene–drug references ('+rows.length+')</summary><p>'+esc(GENE_DRUG_SCOPE)+'</p><p class="small">Selected non-provisional level A/B pairs with guideline links. Retrieved '+esc(geneDrugLibrary.retrievedAt.slice(0,10))+'. <a href="https://cpicpgx.org/prioritization/" target="_blank" rel="noreferrer">CPIC level definitions ↗</a></p>'+rows.map(r=>'<article><h4>'+esc(r.gene)+' · '+esc(r.drug)+'</h4><p class="small">Source CPIC level '+esc(r.level)+' · '+esc(r.drugId)+'</p><a href="'+esc(r.url)+'" target="_blank" rel="noreferrer">'+esc(r.guideline)+' ↗</a></article>').join('')+'</details>';}

function expertAssertionDetails(allele){const rows=allele.expertAssertions||[];if(!rows.length)return '';return '<details class="score-note"><summary>Disease-specific expert assertions ('+rows.length+')</summary><p>'+esc(EXPERT_ASSERTION_SCOPE)+'</p>'+rows.map(r=>'<article><h4>'+esc(r.classification)+' · '+esc(r.disease)+'</h4><p>'+esc(r.inheritance)+' · '+esc(r.mondo)+'</p>'+(expertClassificationDifference(allele.classification,r.classification)?'<p><strong>The source classification differs from the ClinVar label above.</strong> Check the dates and original records; neither has been silently replaced.</p>':'')+'<p class="small">'+esc(r.panel)+' · Approved '+esc(r.approvalDate)+' · Published '+esc(r.publishedDate)+'</p><p class="small mono">'+esc(r.genomicHGVS)+'</p>'+(r.variantKind==='short-indel'?'<p class="small">Converted against the verified reference and matched after normalization: GRCh38 '+esc(r.chrom)+':'+esc(r.position)+' '+esc(r.ref)+' → '+esc(r.alt)+'.</p>':'')+'<p class="small">Source evidence codes met: '+esc(r.evidenceMet.join(', ')||'None supplied')+'<br>Not met: '+esc(r.evidenceNotMet.join(', ')||'None supplied')+'. These codes are reported by the panel; this app does not recalculate the classification.</p><a href="'+esc(r.url)+'" target="_blank" rel="noreferrer">Full expert assertion ↗</a> · <a href="'+esc(r.guidelineURL)+'" target="_blank" rel="noreferrer">Expert panel criteria ↗</a></article>').join('')+'</details>';}

function referenceCard(m){
 const p=m.referenceComparison;
 if(p?.point==null&&p?.lower==null&&Number.isFinite(m.referenceSensitivity?.lower))return sensitivityCard(m);
 if(p.point==null&&p.lower==null){
  const conflicts=(m.terms||[]).filter(t=>['Model allele mismatch','Unsupported call','Allele / ID mismatch','Conflicting records','Overlapping records'].includes(t.status));
  const referenceIssues=m.referenceSensitivity?.blockingReferenceTerms||[];
  return '<div class="score-note"><strong>European reference percentile: unavailable</strong><p>'+esc(p.reason)+'</p>'+(m.referenceSensitivity?.reason?'<p>'+esc(m.referenceSensitivity.reason)+'</p>':'')+(conflicts.length?'<p><strong>Personal-file conflicts:</strong> '+conflicts.map(t=>esc(t.id+' — '+t.status)).join('; ')+'.</p>':'')+(referenceIssues.length?'<p><strong>Reference conflicts:</strong> '+referenceIssues.map(t=>esc(t.id+' — '+t.reason)).join('; ')+'.</p>':'')+((conflicts.length||referenceIssues.length)?'<p>These require compatible allele definitions or resolved variant records. They are not substituted as ordinary missing genotypes.</p>':'')+'</div>';
 }
 const rank=n=>n===null?'Range only':Number.isFinite(n)?n.toLocaleString(undefined,{maximumFractionDigits:1})+' / 100':'Unavailable';
 return '<div class="score-note"><h4>'+(p.measured?'European reference percentile':'What-if European reference percentile')+'</h4><div class="pgs-metrics"><div><small>'+(p.measured?'Measured-score rank':'Common-genotype scenario rank')+'</small><strong>'+rank(p.point)+'</strong></div><div><small>'+(p.measured?'No missing-term range':'Possible percentile range')+'</small><strong>'+(p.measured?'—':rank(p.lower)+' to '+rank(p.upper))+'</strong></div><div><small>European reference individuals</small><strong>'+p.sampleCount+'</strong></div></div><p>'+esc(p.reason)+'</p><p class="small">Percentile rank is not a probability of disease. EUR is your selected comparison, not an assessment of your ancestry. This finite reference sample does not represent every European population.</p>'+(p.outsideReference?'<p class="small">The central score is '+esc(p.outsideReference)+' every score in this reference sample. No rank beyond the observed sample is extrapolated.</p>':'')+'<details><summary>Reference source and calculation</summary><p>'+esc(p.method)+'</p><p class="small">Reference version '+esc(p.referenceVersion)+' · built '+esc(p.retrievedAt?.slice(0,10))+' · <a href="https://pgsc-calc.readthedocs.io/en/latest/how-to/database.html" target="_blank" rel="noreferrer">PGS Catalog 1000 Genomes reference ↗</a></p><p class="small mono">Model SHA-256: '+esc(p.modelSha256)+'<br>Archive SHA-256: '+esc(p.referenceSha256)+'</p></details></div>';
}

function sensitivityCard(m){
 const p=m.referenceSensitivity,rank=x=>Number.isFinite(x)?x.toFixed(1)+'th':'Unavailable';
 return '<div class="score-note"><h4>Percentile sensitivity · European reference</h4><div class="pgs-metrics"><div><small>Lowest possible rank bound</small><strong>'+rank(p.lower)+'</strong></div><div><small>'+(p.scenarioSummary?(p.scenarioSummary.neutralReference?'Scenario median · neutral reference':'Scenario median · assumption-based'):p.comparisonMethod?'Best guess':'Central scenario · neutral assumptions')+'</small><strong>'+(p.scenarioSummary?rank(p.scenarioSummary.median):p.comparisonMethod?'Not established':rank(p.point))+'</strong></div><div><small>Highest possible rank bound</small><strong>'+rank(p.upper)+'</strong></div></div><p>'+esc(p.reason)+'</p>'+(p.scenarioSummary?'<p><strong>'+(p.scenarioSummary.neutralReference?'Neutral-reference scenario range: ':p.missingGenotypes?'Common-genotype scenario range: ':'Consistent scenario range: ')+''+rank(p.scenarioSummary.lower)+' to '+rank(p.scenarioSummary.upper)+'</strong></p><p>'+esc(p.scenarioSummary.method)+'</p>':'')+'<p class="small">'+p.sampleCount+' EUR reference individuals; '+p.uncertainReferenceTerms+' reference terms have unresolved allele orientation ('+pct(p.uncertainWeightFraction)+' of absolute weight). '+(p.comparisonMethod?(p.scenarioCount===null?'Conservative comparisons with shared allele directions.':p.scenarioCount+' consistent allele-direction scenarios were evaluated.'):'Common missing genotypes are used where available; remaining contribution ranges use their midpoints.')+' This is not a measured or calibrated population percentile.</p>'+(p.scenarios?.length?'<details><summary>Review '+p.scenarioCount+' consistent scenarios</summary>'+p.scenarios.map((x,i)=>'<p>Scenario '+(i+1)+': '+rank(x.lower)+(!Number.isFinite(x.lower)||!Number.isFinite(x.upper)||Math.abs(x.lower-x.upper)>1e-9?' to '+rank(x.upper):'')+' percentile'+(Number.isFinite(x.centralRank)?' · central scenario '+rank(x.centralRank):'')+' · '+(Object.entries(x.alleles??{}).map(([id,a])=>esc(id+' → '+a)).join(', ')||'Allele choices not recorded')+'</p>').join('')+'</details>':'')+'<details><summary>Why this is a sensitivity comparison</summary><p>'+esc(m.referenceComparison.reason)+'</p><p>'+esc(p.method)+'</p><p class="small mono">Model SHA-256: '+esc(p.modelSha256)+'<br>Reference SHA-256: '+esc(p.referenceSha256)+'</p></details></div>';
}

function renderWorkspaceViews(){
 $('ancestry-results').hidden=activeView!=='ancestry';$('ancestry-view').setAttribute('aria-pressed',String(activeView==='ancestry'));
 if(activeView==='ancestry'){$('ancestry-results').innerHTML=ancestryHtml(report.ancestry,{demo:report.syntheticDemo});$('empty').hidden=true;$('result-count').textContent='Ancestry · broad reference mixture and sampled population similarity';}
 $('overview-results').hidden=activeView!=='overview';$('investigate-results').hidden=activeView!=='investigate';
 for(const v of ['overview','investigate'])$(v+'-view').setAttribute('aria-pressed',String(activeView===v));
 if(activeView==='overview'){$('overview-results').innerHTML=overviewHtml(report);$('empty').hidden=true;$('result-count').textContent='Whole-report overview · independent of variant filters';}
 if(activeView==='investigate'){$('investigate-results').innerHTML=investigationHtml(report,$('search').value);$('empty').hidden=true;$('result-count').textContent='Prioritize unresolved model terms · search variant, model, trait or status';}
 if(savedSnapshot){$('snapshot-status').textContent=europeanSnapshotNotice(report,pgsLibrary,snapshotMigrationCount);}
}
let savingAnalysis=false;
async function downloadJson(value,name){
 if(savingAnalysis)return;
 savingAnalysis=true;$('save-analysis').disabled=true;$('export').disabled=true;
 const status=$('save-status');status.textContent='Preparing analysis for saving…';
 try{
  await new Promise(resolve=>setTimeout(resolve,0));
  const text=serializeAnalysis(value);
  if(window.genomeDesktop?.saveAnalysis){
   status.textContent='Choose a location in the Save dialog…';
   const result=await window.genomeDesktop.saveAnalysis({name,text});
   status.textContent=result?'Analysis saved to '+result.path:'Save cancelled. Your analysis is still open.';
   if(result){clearError();$('status').textContent=status.textContent;}
  }else{
   const url=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
   status.textContent='JSON download started. Check your browser downloads.';
  }
 }catch(e){status.textContent='Unable to save analysis: '+e.message;error(status.textContent);}
 finally{savingAnalysis=false;$('save-analysis').disabled=false;$('export').disabled=false;}
}
function currentUi(){return {activeView,scenarioPopulation,scoreBrowse,organizer,researchFilters,selectedScore,search:$('search').value,category:$('category').value,show:$('show').value,sort:$('sort').value};}
$('save-analysis').addEventListener('click',()=>{if(!report||worker){$('save-status').textContent='Wait for a completed analysis before saving.';return;}downloadJson(saveWorkspace(report,currentUi(),$('analysis-notes').value),'genome-workspace-'+new Date().toISOString().slice(0,10)+'.json');});
function bindSavedPicker(id,handler){
 const input=$(id);input.addEventListener('change',handler);
 if(window.genomeDesktop?.openAnalysis)input.addEventListener('click',async event=>{
  event.preventDefault();
  if(worker||!catalog){error('Wait for reference loading or cancel the active scan first.');return;}
  try{const selected=await window.genomeDesktop.openAnalysis();if(selected)await handler({target:{files:[new File([selected.text],selected.name,{type:'application/json'})],value:''}});}catch(e){error('Unable to open analysis: '+e.message);}
 });
}
async function readSavedFile(file){if(!file)throw Error('Choose a saved analysis.');if(file.size>150_000_000)throw Error('Saved analysis exceeds 150 MB.');return validateSaved(JSON.parse(await file.text()));}
bindSavedPicker('reopen-analysis',async event=>{try{
 if(worker||!catalog)throw Error('Wait for reference loading or cancel the active scan first.');
 const saved=await readSavedFile(event.target.files[0]);clearReport();clearError();report=saved.report;isDemo=!!report.syntheticDemo;savedSnapshot=true;
 const ui=saved.ui;organizer=normalizeOrganizer(ui.organizer,report);researchFilters=ui.researchFilters&&typeof ui.researchFilters==='object'?{family:typeof ui.researchFilters.family==='string'?ui.researchFilters.family:'',kind:typeof ui.researchFilters.kind==='string'?ui.researchFilters.kind:'',coverage:typeof ui.researchFilters.coverage==='string'?ui.researchFilters.coverage:'',eligibility:typeof ui.researchFilters.eligibility==='string'?ui.researchFilters.eligibility:'',pinned:ui.researchFilters.pinned===true}:{};selectedScore=report.polygenicScores.some(m=>m.id===ui.selectedScore)?ui.selectedScore:null;scoreBrowse=scoreBrowseOptions(ui.scoreBrowse);if(ui.activeView==='diseases')ui.activeView='scores';activeView=['overview','investigate','traits','variants','scores','key-genes','ancestry'].includes(ui.activeView)?ui.activeView:'overview';
 const migrated=migrateEuropeanSnapshot(report,pgsPopulations,scoreReference,sensitivityReference);snapshotMigrationCount=migrated;if(migrated)report.warnings.push('Reopened analysis: '+migrated+' non-European score scenarios recalculated with European references; measured calls retained.');
 if(typeof ui.category==='string'&&ui.category&&![...$('category').options].some(o=>o.value===ui.category)){const option=document.createElement('option');option.value=ui.category;option.textContent=ui.category;$('category').append(option);}
 for(const id of ['search','category','show','sort'])if(typeof ui[id]==='string')$(id).value=ui[id];
 if(!$('show').value)$('show').value='all';if(!$('sort').value)$('sort').value='priority';
 $('analysis-notes').value=saved.notes;$('report-area').hidden=false;$('report-label').textContent=isDemo?'SAVED SYNTHETIC REPORT':'SAVED LOCAL REPORT';$('report-name').textContent='Reopened analysis';$('report-meta').textContent=report.build+' · '+(report.sample||'Sample unspecified')+' · '+(report.inputFile||'Saved report');
 renderRecordCoverage();$('present').textContent=report.results.filter(r=>r.copies>0).length;$('issues').textContent=report.results.filter(issue).length;$('scanned').textContent=report.stats.records.toLocaleString();$('warnings').innerHTML=report.warnings.map(w=>'<li>'+esc(w)+'</li>').join('');
 render();$('status').textContent=migrated?'Saved analysis reopened locally; non-European scenarios updated to EUR.':'Saved analysis reopened locally without rescanning or recalculating scores.';
 }catch(e){error(e.message);}finally{event.target.value='';}});
bindSavedPicker('compare-analysis',async event=>{try{
 if(!report||worker)throw Error('Open a completed analysis first.');const saved=await readSavedFile(event.target.files[0]),rows=compareReports(saved.report,report);
 const ancestryComparison=ancestryComparisonHtml(saved.report.ancestry,report.ancestry);
 const previous=new Map(saved.report.results.map(r=>[r.id,r]));let changed=0,added=0;for(const r of report.results){const old=previous.get(r.id);if(!old)added++;else if(old.status!==r.status||old.genotype!==r.genotype||old.interpretation!==r.interpretation)changed++;previous.delete(r.id);}
 $('analysis-comparison').innerHTML='<h3>Saved → current analysis</h3><p>'+changed+' variant entries changed call/status/interpretation; '+added+' added; '+previous.size+' removed. These can reflect library changes, not biological change. Sample names match, but do not independently prove specimen identity.</p><div class="table-wrap"><table><thead><tr><th>Model</th><th>What changed</th><th>Previous → current percentile summary</th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+esc(r.id+' · '+r.trait)+'</td><td>'+esc(r.reason)+'</td><td>'+esc(comparisonDescription(r.before))+' → '+esc(comparisonDescription(r.after))+'</td></tr>').join('')+'</tbody></table></div>'+(!rows.length?'<p>No score changes detected in the stored comparison fields.</p>':'');
 $('analysis-comparison').insertAdjacentHTML('afterbegin',ancestryComparison);
 }catch(e){error(e.message);}finally{event.target.value='';}});
$('overview-results').addEventListener('click',event=>{const v=event.target.closest('[data-open-view]'),r=event.target.closest('[data-overview-variant]');if(v){activeView=v.dataset.openView;$('search').value='';render();}if(r)details(r.dataset.overviewVariant);});
$('investigate-results').addEventListener('click',event=>{const b=event.target.closest('[data-inspect-model]');if(!b)return;const m=report.polygenicScores.find(m=>m.id===b.dataset.inspectModel),t=m.terms.find(t=>t.id===b.dataset.inspectTerm),entry=report.results.find(r=>r.id===t.id);
 $('investigation-content').innerHTML='<h2>'+esc(t.id)+' · '+esc(scoreDisplayTrait(m))+'</h2><p>'+esc(m.id)+' · '+esc(report.build)+' '+esc(t.mapping?.chrom)+':'+esc(t.mapping?.position)+'</p><p><strong>'+esc(t.status)+'</strong> · stored genotype '+esc(t.genotype)+'</p><p>Model effect allele '+esc(t.effectAllele)+'; other allele '+esc(t.otherAllele||'not specified')+'; weight '+esc(t.weightText||t.weight)+'.</p><p>'+esc(t.note||'No additional score-level note stored.')+'</p><h3>Stored evidence</h3><p>'+esc(entry?.notes?JSON.stringify(entry.notes):'This report does not retain read alignments or full VCF FORMAT evidence for this site.')+'</p><p>Normalization accepted: '+(report.shortVariantNormalizationAccepted?'yes':'no')+'. A normalized file can still contain biologically overlapping variants. Resolving those may require haplotype-aware review.</p><label for="evidence-records">Optional local VCF excerpt (include the header for multiple samples)</label><textarea id="evidence-records" rows="5" maxlength="1000000"></textarea><button class="secondary" id="inspect-evidence">Inspect excerpt</button><div id="evidence-output"></div><p>Evidence is displayed locally and is not saved or used to override calls. Include overlapping records around the displayed position; this is not an alignment viewer or a new variant call.</p>';
 $('inspect-evidence').addEventListener('click',()=>{try{const rows=parseEvidence($('evidence-records').value,report.sample).filter(r=>r.chrom.replace(/^chr/,'')===String(t.mapping?.chrom).replace(/^chr/,'')&&r.position<=t.mapping.position+5&&r.position+Math.max(1,r.ref.length)-1>=t.mapping.position-5);$('evidence-output').innerHTML='<pre>'+esc(JSON.stringify(rows,null,2))+'</pre>'+(rows.length?'':'<p>No records overlap the selected region.</p>');}catch(e){$('evidence-output').textContent=e.message;}});
 $('investigation-dialog').showModal();});
$('close-investigation').addEventListener('click',()=>{$('investigation-dialog').close();$('investigation-content').replaceChildren();});

function comparisonDescription(r){if(!r)return 'Not present';const rank=x=>Number.isFinite(x)?x.toFixed(1):'—';return r.label+' · '+rank(r.point)+(r.lower!==null?' (range '+rank(r.lower)+'–'+rank(r.upper)+')':'');}

function renderResearchList(){
 const entries=[...report.polygenicScores.map(m=>({key:'score:'+m.id,label:scoreDisplayTrait(m)+' · '+m.id,id:m.id,score:true})),...report.results.map(r=>({key:'variant:'+r.id,label:r.gene+' · '+r.id,id:r.id}))].filter(r=>organizer[r.key]?.pinned||organizer[r.key]?.reviewed||organizer[r.key]?.note);
 $('research-list').innerHTML=entries.length?'<h3>My research</h3><p>Selections and notes are kept when you save this analysis locally.</p>'+entries.map(r=>'<p><button class="secondary" '+(r.score?'data-open-score':'data-open-variant')+'="'+esc(r.id)+'">'+esc(r.label)+'</button> '+(organizer[r.key]?.pinned?'★ Pinned · ':'')+(organizer[r.key]?.reviewed?'Reviewed':'Not reviewed')+(organizer[r.key]?.note?' · Has note':'')+'</p>').join(''):'<p>Pin scores or variants, mark them reviewed, and add notes in their detail view.</p>';
}
document.addEventListener('click',event=>{
 const pin=event.target.closest('[data-pin]');if(pin&&report){const key=pin.dataset.pin;organizer[key]={...organizer[key],pinned:!organizer[key]?.pinned};pin.textContent=organizer[key].pinned?'★ Pinned':'☆ Pin';pin.setAttribute('aria-pressed',String(organizer[key].pinned));renderResearchList();for(const other of document.querySelectorAll('[data-pin]'))if(other.dataset.pin===key){other.setAttribute('aria-pressed',String(organizer[key].pinned));other.textContent=organizer[key].pinned?'★ Pinned':'☆ Pin';}if(researchFilters.pinned)renderScores();return;}
 const reset=event.target.closest('[data-reset-research]');if(reset){researchFilters={};scoreBrowse=scoreBrowseOptions();$('search').value='';renderScores();return;}
 const score=event.target.closest('[data-open-score],a[href^="#score-"]');if(score&&report){event.preventDefault();selectedScore=score.dataset.openScore||score.getAttribute('href').slice(7);if(score.dataset.openScore){activeView='scores';researchFilters={};scoreBrowse=scoreBrowseOptions();$('search').value='';render();}else renderScores();$('score-'+selectedScore)?.querySelector('h3')?.focus();$('score-'+selectedScore)?.scrollIntoView({block:'start',behavior:'smooth'});return;}
 const variant=event.target.closest('[data-open-variant]');if(variant)details(variant.dataset.openVariant);
});
document.addEventListener('change',event=>{
 if(event.target.matches('[data-reviewed]')){const key=event.target.dataset.reviewed;organizer[key]={...organizer[key],reviewed:event.target.checked};renderResearchList();}
 if(event.target.matches('[data-research-filter]')){const key=event.target.dataset.researchFilter;researchFilters[key]=event.target.type==='checkbox'?event.target.checked:event.target.value;renderScores();$('pgs-results').querySelector('[data-research-filter="'+key+'"]').focus();}
});
document.addEventListener('input',event=>{if(event.target.matches('[data-item-note]')){const key=event.target.dataset.itemNote;organizer[key]={...organizer[key],note:event.target.value};renderResearchList();}});
