$('download-readable').addEventListener('click',()=>{const content='<!doctype html><html lang="en"><meta charset="utf-8"><title>Genome research report</title><style>body{font:16px/1.5 system-ui;max-width:900px;margin:2rem auto;padding:1rem;color:#172c35}article{border-top:1px solid #bbb;padding:1rem 0;break-inside:avoid}a{overflow-wrap:anywhere}.private-note{white-space:pre-wrap}@media print{body{margin:0}}</style>'+ $('print-report').innerHTML+'</html>';const url=URL.createObjectURL(new Blob([content],{type:'text/html'})),a=document.createElement('a');a.href=url;a.download='genome-selected-research.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});

